                  "source": "neither deference nor dismissal",
                  "target": "không phải là nghe theo hay gạt bỏ"
                },
                {
                  "source": "calibrate the trust",
                  "target": "điều chỉnh niềm tin"
                },
                {
                  "source": "the environment actually warrants",
                  "target": "mức môi trường thực sự cho phép"
                }
              ]
            }
