            {
              "id": "p3-s1",
              "source": "How do bees do all this work?",
              "translation_vi": "Ong làm tất cả những việc này bằng cách nào?",
              "precision": "sentence",
              "phrases": [
                {
                  "source": "all this work",
                  "target": "tất cả những việc này"
                }
              ]
